import{_ as e,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Exibir nomes dos usuários nos eventos","description":"","frontmatter":{"title":"Exibir nomes dos usuários nos eventos","id":"eproc-exibir-nomes-usuarios","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.0.2","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-exibir-nomes-usuarios.md","filePath":"funcionalidades/eproc-exibir-nomes-usuarios.md"}'),t={name:"funcionalidades/eproc-exibir-nomes-usuarios.md"};function i(n,a,d,u,l,c){return o(),s("div",null,a[0]||(a[0]=[r('<h1 id="exibir-nomes-dos-usuarios-nos-eventos" tabindex="-1">Exibir nomes dos usuários nos eventos <a class="header-anchor" href="#exibir-nomes-dos-usuarios-nos-eventos" aria-label="Permalink to &quot;Exibir nomes dos usuários nos eventos&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O eproc identifica quem lançou cada evento ou minuta só pela matrícula. Este recurso mostra o nome completo ao lado da matrícula. Também mostra o nome do advogado ao lado da OAB citada na descrição de um evento.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>:</p><ul><li>página do processo: eventos, observações &quot;Criado por/Editado por&quot; e lembretes;</li><li>área de trabalho de minutas e cadastro de minuta: tabela de minutas, inclusive &quot;Assinante indicado&quot; e rótulos como &quot;Para assinar (f0000000)&quot;.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo. Ao lado de cada matrícula aparece o nome do usuário.</li><li>As OABs citadas na descrição dos eventos ganham o nome do advogado ao lado.</li></ol><p>Os nomes ficam guardados neste navegador, para aparecerem também em outras telas do eproc.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Desativar o balão que aparece ao passar o mouse sobre a matrícula</td><td>desligada</td><td>Esconde o balão nativo do eproc, já que o nome passa a aparecer na tela.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O nome vem das informações que o próprio eproc mostra (o balão da matrícula nos eventos e a tabela de partes). Uma matrícula que o eploc ainda não viu em nenhuma dessas telas continua só com o número.</li><li>Os advogados entram pela tabela de partes, mesmo que ainda não tenham se manifestado no processo.</li></ul>',13)]))}const b=e(t,[["render",i]]);export{p as __pageData,b as default};
